int xxbyte_python_printable(uint32_t cp, uint32_t minor)
{
    size_t lo = 0;
    size_t hi = sizeof(python_printable_ranges) / sizeof(python_printable_ranges[0]);

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (cp < python_printable_ranges[mid].first) {
            hi = mid;
        } else if (cp > python_printable_ranges[mid].last) {
            lo = mid + 1;
        } else {
            return minor >= python_printable_ranges[mid].since;
        }
    }
    return 0;
}

